+import Yoga from 'yoga-layout';
+import {type DOMElement, type DOMNode} from './dom.js';
+
+type Track =
+	| {type: 'fixed'; size: number}
+	| {type: 'fr'; fraction: number}
+	| {type: 'auto'}
+	| {type: 'minmax'; min: number; max: number | {fraction: number}};
+
+type Placement = {start?: number; end?: number};
+type Area = {column: Required<Placement>; row: Required<Placement>};
+
+const trackPattern = /minmax\\(\\s*([\\d.]+)\\s*,\\s*([\\d.]+(?:fr)?)\\s*\\)|([\\d.]+(?:fr)?|auto)/g;
+
+const parseTracks = (template: string | undefined): Track[] => {
+	if (!template) {
+		return [];
+	}
+
+	const tracks: Track[] = [];
+	for (const match of template.matchAll(trackPattern)) {
+		if (match[1] && match[2]) {
+			const max = match[2].endsWith('fr')
+				? {fraction: Number.parseFloat(match[2])}
+				: Number.parseFloat(match[2]);
+			tracks.push({type: 'minmax', min: Number.parseFloat(match[1]), max});
+			continue;
+		}
+
+		const value = match[3]!;
+		if (value === 'auto') {
+			tracks.push({type: 'auto'});
+		} else if (value.endsWith('fr')) {
+			tracks.push({type: 'fr', fraction: Number.parseFloat(value)});
+		} else {
+			tracks.push({type: 'fixed', size: Number.parseFloat(value)});
+		}
+	}
+
+	return tracks;
+};
+
+const parsePlacement = (value: number | string | undefined): Placement => {
+	if (typeof value === 'number') {
+		return {start: value - 1, end: value};
+	}
+
+	if (typeof value !== 'string') {
+		return {};
+	}
+
+	const [start, end] = value.split('/').map(part => Number.parseInt(part.trim(), 10));
+	if (!Number.isFinite(start)) {
+		return {};
+	}
+
+	return Number.isFinite(end)
+		? {start: start - 1, end: end - 1}
+		: {start: start - 1, end: start};
+};
+
+const isGrid = (node: DOMElement): boolean => node.style.display === 'grid';
+
+const gridChildren = (node: DOMElement): DOMElement[] =>
+	node.childNodes.filter(
+		(child): child is DOMElement =>
+			child.nodeName !== '#text' && Boolean(child.yogaNode),
+	);
+
+const overlaps = (a: Area, b: Area): boolean =>
+	a.column.start < b.column.end &&
+	a.column.end > b.column.start &&
+	a.row.start < b.row.end &&
+	a.row.end > b.row.start;
+
+const placeChildren = (children: DOMElement[], columns: number): Map<DOMElement, Area> => {
+	const areas = new Map<DOMElement, Area>();
+	const occupied: Area[] = [];
+
+	for (const child of children) {
+		const column = parsePlacement(child.style.gridColumn);
+		const row = parsePlacement(child.style.gridRow);
+		const columnSpan = Math.max(1, (column.end ?? (column.start ?? 0) + 1) - (column.start ?? 0));
+		const rowSpan = Math.max(1, (row.end ?? (row.start ?? 0) + 1) - (row.start ?? 0));
+
+		let candidate: Area | undefined;
+		for (let rowIndex = row.start ?? 0; !candidate; rowIndex++) {
+			if (row.start !== undefined && rowIndex !== row.start) {
+				break;
+			}
+
+			for (let columnIndex = column.start ?? 0; columnIndex < columns; columnIndex++) {
+				if (column.start !== undefined && columnIndex !== column.start) {
+					break;
+				}
+
+				const area = {
+					column: {start: columnIndex, end: columnIndex + columnSpan},
+					row: {start: rowIndex, end: rowIndex + rowSpan},
+				};
+				if (area.column.end <= columns && !occupied.some(other => overlaps(area, other))) {
+					candidate = area;
+					break;
+				}
+			}
+		}
+
+		if (candidate) {
+			areas.set(child, candidate);
+			occupied.push(candidate);
+		}
+	}
+
+	return areas;
+};
+
+const resolveTracks = (
+	tracks: Track[],
+	available: number | undefined,
+	gap: number,
+	intrinsic: number[],
+): number[] => {
+	const sizes = tracks.map((track, index) => {
+		if (track.type === 'fixed') return track.size;
+		if (track.type === 'auto') return intrinsic[index] ?? 0;
+		if (track.type === 'minmax') {
+			return typeof track.max === 'number'
+				? Math.min(track.max, Math.max(track.min, intrinsic[index] ?? 0))
+				: track.min;
+		}
+
+		return available === undefined ? (intrinsic[index] ?? 0) : 0;
+	});
+
+	if (available === undefined) {
+		return sizes;
+	}
+
+	const remaining = available - sizes.reduce((sum, size) => sum + size, 0) - gap * Math.max(0, tracks.length - 1);
+	const fractions = tracks.reduce((sum, track) => {
+		if (track.type === 'fr') return sum + track.fraction;
+		return track.type === 'minmax' && typeof track.max !== 'number'
+			? sum + track.max.fraction
+			: sum;
+	}, 0);
+
+	if (remaining > 0 && fractions > 0) {
+		for (const [index, track] of tracks.entries()) {
+			if (track.type === 'fr') sizes[index] += (remaining * track.fraction) / fractions;
+			if (track.type === 'minmax' && typeof track.max !== 'number') {
+				sizes[index] += (remaining * track.max.fraction) / fractions;
+			}
+		}
+	}
+
+	return sizes;
+};
+
+const positions = (sizes: number[], gap: number): number[] => {
+	let position = 0;
+	return sizes.map(size => {
+		const current = position;
+		position += size + gap;
+		return current;
+	});
+};
+
+const applyGrid = (node: DOMElement): void => {
+	const yogaNode = node.yogaNode!;
+	const children = gridChildren(node);
+	const columnTracks = parseTracks(node.style.gridTemplateColumns);
+	const columns = Math.max(1, columnTracks.length);
+	const areas = placeChildren(children, columns);
+	const rowTracks = parseTracks(node.style.gridTemplateRows);
+	const rowCount = Math.max(
+		rowTracks.length,
+		...Array.from(areas.values(), area => area.row.end),
+		1,
+	);
+	while (columnTracks.length < columns) columnTracks.push({type: 'auto'});
+	while (rowTracks.length < rowCount) rowTracks.push({type: 'auto'});
+
+	const columnGap = yogaNode.getGap(Yoga.GUTTER_COLUMN).value;
+	const rowGap = yogaNode.getGap(Yoga.GUTTER_ROW).value;
+	const width = yogaNode.getComputedWidth() - yogaNode.getComputedPadding(Yoga.EDGE_LEFT) - yogaNode.getComputedPadding(Yoga.EDGE_RIGHT);
+	const height = yogaNode.getComputedHeight() - yogaNode.getComputedPadding(Yoga.EDGE_TOP) - yogaNode.getComputedPadding(Yoga.EDGE_BOTTOM);
+	const columnIntrinsic = Array<number>(columns).fill(0);
+	const rowIntrinsic = Array<number>(rowCount).fill(0);
+
+	for (const [child, area] of areas) {
+		if (area.column.end - area.column.start === 1) {
+			columnIntrinsic[area.column.start] = Math.max(columnIntrinsic[area.column.start]!, child.yogaNode!.getComputedWidth());
+		}
+		if (area.row.end - area.row.start === 1) {
+			rowIntrinsic[area.row.start] = Math.max(rowIntrinsic[area.row.start]!, child.yogaNode!.getComputedHeight());
+		}
+	}
+
+	const columnSizes = resolveTracks(columnTracks, width, columnGap, columnIntrinsic);
+	const rowSizes = resolveTracks(rowTracks, node.style.height === undefined ? undefined : height, rowGap, rowIntrinsic);
+	const columnPositions = positions(columnSizes, columnGap);
+	const rowPositions = positions(rowSizes, rowGap);
+
+	if (node.style.height === undefined) {
+		yogaNode.setHeight(rowSizes.reduce((sum, size) => sum + size, 0) + rowGap * Math.max(0, rowSizes.length - 1));
+	}
+
+	for (const [child, area] of areas) {
+		const childYogaNode = child.yogaNode!;
+		const childWidth = columnSizes.slice(area.column.start, area.column.end).reduce((sum, size) => sum + size, 0) + columnGap * Math.max(0, area.column.end - area.column.start - 1);
+		const childHeight = rowSizes.slice(area.row.start, area.row.end).reduce((sum, size) => sum + size, 0) + rowGap * Math.max(0, area.row.end - area.row.start - 1);
+		childYogaNode.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
+		childYogaNode.setPosition(Yoga.EDGE_LEFT, columnPositions[area.column.start]!);
+		childYogaNode.setPosition(Yoga.EDGE_TOP, rowPositions[area.row.start]!);
+		childYogaNode.setWidth(childWidth);
+		childYogaNode.setHeight(childHeight);
+	}
+};
+
+const visit = (node: DOMNode): void => {
+	if (node.nodeName === '#text') return;
+	if (isGrid(node)) applyGrid(node);
+	for (const child of node.childNodes) visit(child);
+};
+
+export const calculateLayout = (rootNode: DOMElement, width: number): void => {
+	rootNode.yogaNode!.setWidth(width);
+	rootNode.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+
+	// A first pass resolves parent dimensions; a second resolves nested grids after
+	// their grid area has been assigned by the parent.
+	for (let index = 0; index < 2; index++) {
+		visit(rootNode);
+		rootNode.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+	}
+};
